'use strict';
const KEY='work-english-lab-v1';
const blank=()=>({version:1,completed:[],checks:{},daily:{},drafts:{},logs:[],quizResults:[],assessments:[],notes:'',vocabProgress:{},vocabLastChapter:1});
let state=blank(),storageOK=true,activeQuiz=null,quizTimer=null,recorder=null,audioURL=null,toastTimer=null;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1)state={...blank(),...saved};}catch{storageOK=false;}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today=()=>dateKey();
const course=id=>COURSES.find(c=>c.id===Number(id))||COURSES[0];
const resource=id=>RESOURCES.find(r=>r.id===id);
const totalMinutes=()=>state.logs.reduce((a,x)=>a+(Number(x.minutes)||0),0);
const nextCourse=()=>COURSES.find(c=>!state.completed.includes(c.id))||COURSES[11];
const wc=t=>(t.match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]).length;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;toast('浏览器存储不可用，请导出学习记录备份。');}updateSide();}
function updateSide(){$('#side-progress').style.width=`${state.completed.length/12*100}%`;$('#side-caption').textContent=`${state.completed.length} / 12 模块已完成`;if(!storageOK)$('.local-badge').textContent='存储受限，请导出备份';}
function download(name,content,type='text/plain;charset=utf-8'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('已复制，可粘贴到支持的对话工具中练习。');}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();const ok=document.execCommand('copy');t.remove();toast(ok?'已复制。':'复制不可用，请手动选择文本复制。');}}
const pageHead=(eyebrow,title,desc,extra='')=>`<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p class="sub">${desc}</p></div>${extra}</div>`;
const sourceLink=r=>`<a class="resource-mini" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗<small>${esc(r.org)} · ${esc(r.level)}</small></a>`;
function courseCard(c){const done=state.completed.includes(c.id);return `<a class="course-card" href="#lesson/${c.id}"><div class="course-top"><span class="week-number">WEEK ${String(c.week).padStart(2,'0')}</span><span class="chip">${c.track}</span></div><h3>${c.title}</h3><div class="en-title">${c.en}</div><p>${c.desc}</p><div class="card-bottom"><span class="${done?'completion':''}">${done?'✓ 已完成':'表达 · 实践 · 自测'}</span><span class="circle-arrow">↗</span></div></a>`;}
function home(){const c=nextCourse(),day=state.daily[today()]||{},mins=state.logs.filter(l=>l.date===today()).reduce((s,l)=>s+l.minutes,0);const tasks=[['听懂关键事实','15','听一小段，记责任人、时间和待确认事项'],['跟读与录音','10','30—60秒，听清数字和关键词'],['开口完成业务任务','25',c.speaking],['写出一封邮件或摘要','25',c.writing],['复用5个表达 + 记录','15','10分钟复习，5分钟记录三个错误']];$('#main').innerHTML=pageHead('A LITTLE EVERY DAY','让英语，成为你的工作能力。','从面试介绍到项目周会，从数据结论到邮件跟进。每天90分钟，围绕一个真实任务练习。',`<span class="date-note">${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>`)+`<div class="hero-grid"><section class="hero"><div class="hero-copy"><div class="hero-tag">YOUR NEXT STEP · WEEK ${String(c.week).padStart(2,'0')}</div><h2>${c.title}<br><span style="font-family:Georgia;font-size:.7em">${c.en}</span></h2><p>${c.goal}</p><a class="btn" href="#lesson/${c.id}">开始今日课程 <span>↗</span></a></div><svg class="hero-art" viewBox="0 0 170 210" fill="none" aria-hidden="true"><rect x="25" y="72" width="108" height="134" rx="8" fill="#b4c480" transform="rotate(-10 25 72)"/><rect x="51" y="40" width="108" height="134" rx="8" fill="#f8f8df" transform="rotate(8 51 40)"/><path d="M70 75l65 10M67 91l56 8M64 107l62 9M61 123l40 6" stroke="#7d9160" stroke-width="3"/><circle cx="43" cy="47" r="20" fill="#c6d894"/><path d="M34 47l6 6 13-14" stroke="#526b3e" stroke-width="3"/><path d="M128 171l16-15 5 21" stroke="#617b46" stroke-width="3"/></svg></section><section class="quick-card"><div><span class="tiny">KNOW YOUR STARTING POINT</span><h3>先测一次，<br>再把力气用对地方。</h3><p>60分钟综合初测，覆盖听、读、邮件、口头汇报与互动。另有25题即时测验，包含词汇与业务判断。</p></div><a class="arrow-link" href="#tests">进入测试中心 ↗</a></section></div><div class="section-head"><h2>今天的90分钟</h2><span>每周6天 · 周六测试与订正</span></div><div class="two-col"><section class="panel">${tasks.map((t,i)=>`<label class="task-row"><input type="checkbox" class="task-check" data-daily="${i}" ${day[i]?'checked':''}><div><div class="task-name">${t[0]}</div><div class="task-help">${i===2?'打开今日课程，录一段不照稿的表达':i===3?'在练习工作台写首稿，再修改':t[2]}</div></div><span class="task-min">${t[1]} <small>MIN</small></span></label>`).join('')}<div class="btn-row"><button class="btn secondary small" data-action="log-today">记录今天实际用时</button><span class="sub">勾选任务不会自动增加学习时长。</span></div></section><section class="panel"><span class="eyebrow">YOUR PACE</span><h2>按自己的节奏，稳步向前。</h2><p class="sub">统计学背景 · 四级528 / 六级478<br>主线：制造业外企项目管理 / 数据分析</p><div class="mini-stat-grid"><div class="mini-stat"><strong>${state.completed.length}<span style="display:inline;font:11px sans-serif"> /12</span></strong><span>模块完成</span></div><div class="mini-stat"><strong>${(totalMinutes()/60).toFixed(1)}</strong><span>累计小时</span></div><div class="mini-stat"><strong>${mins}</strong><span>今日分钟</span></div></div><div class="note">第一天建议：60分钟初测 + 15分钟语法词汇定位 + 15分钟整理。无需先读全部课程。</div></section></div><div class="section-head"><h2>你的12周路线</h2><a href="#courses">查看完整课程 ↗</a></div><div class="week-strip">${COURSES.map(x=>`<a href="#lesson/${x.id}" class="week-tile ${state.completed.includes(x.id)?'done':x.id===c.id?'current':''}" title="${x.title}"><span>WEEK</span><b>${String(x.week).padStart(2,'0')}</b></a>`).join('')}</div><div class="section-head"><h2>这一阶段，先练这些</h2><span>学会一项，再换情境复用</span></div><div class="course-grid">${COURSES.slice(Math.min(c.id-1,9),Math.min(c.id-1,9)+3).map(courseCard).join('')}</div>`;mountVocabularyHome();}
function courses(){const params=new URLSearchParams((location.hash.split('?')[1]||'')),track=params.get('track')||'全部',q=params.get('q')||'';const list=COURSES.filter(c=>(track==='全部'||c.track===track)&&(c.title+c.en+c.desc).toLowerCase().includes(q.toLowerCase()));$('#main').innerHTML=pageHead('THE LEARNING PATH','12周，从会看到会用。','前两周先支持秋招；第3—8周练核心业务场景；后四周练陌生任务与岗位应用。所有模块均可自由进入。')+`<div class="filter-bar">${['全部','共通','项目管理','数据分析'].map(t=>`<button class="filter-btn ${t===track?'active':''}" data-track="${t}">${t}</button>`).join('')}<label class="sr-only" for="course-search">搜索课程</label><input class="search" id="course-search" value="${esc(q)}" placeholder="搜索场景或关键词…"></div><div class="course-grid">${list.length?list.map(courseCard).join(''):'<div class="empty">没有找到匹配模块，试试“邮件”或“数据”。</div>'}</div><div class="note">课程中的工厂、人物和业务数字均为模拟。面试故事请使用真实可核实的个人经历。</div>`;}
function lesson(id){const c=course(id),checks=state.checks[c.id]||{},done=state.completed.includes(c.id);$('#main').innerHTML=`<a class="article-link muted" href="#courses">← 返回12周课程</a><div class="page-head" style="margin-top:25px"><div class="lesson-top"><div class="lesson-no">${String(c.week).padStart(2,'0')}</div><div><span class="eyebrow">WEEK ${c.week} / ${c.track}</span><h1>${c.title}</h1><p class="sub">${c.en} · ${c.goal}</p></div></div></div><div class="lesson-layout"><div class="lesson-content"><section class="panel"><span class="eyebrow">01 / LEARN THE PATTERN</span><h2>先掌握一个表达框架</h2><p>${c.focus}</p><div class="framework">${c.framework}</div>${c.phrases.map(p=>`<div class="phrase"><div class="phrase-en">${esc(p[0])}</div><div class="phrase-cn">${esc(p[1])}</div></div>`).join('')}</section><section class="panel"><span class="eyebrow">02 / SEE IT IN CONTEXT</span><h2>把表达放进工作里</h2><div class="english-text">${esc(c.sample)}</div><p class="sub">${c.translation}</p><div class="btn-row"><button class="btn secondary small" data-action="speak-sample" data-id="${c.id}">▷ 示范朗读</button><button class="btn secondary small" data-action="copy-sample" data-id="${c.id}">复制表达示例</button></div><p class="source-note">示范朗读使用浏览器合成语音，仅供跟读；可用声音取决于设备，不作为听力测评材料。</p></section><section class="panel"><span class="eyebrow">03 / PRACTISE THE TASK</span><h2>轮到你来完成</h2><h3>说出来</h3><p>${c.speaking}</p><h3 style="margin-top:20px">写下来</h3><p>${c.writing}</p><ol class="step-list">${c.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="btn-row"><a class="btn" href="#practice/${c.id}">进入练习工作台 ↗</a><button class="btn secondary" data-action="lesson-quiz" data-id="${c.id}">做本模块小测</button></div></section></div><aside class="lesson-aside"><section class="panel"><span class="eyebrow">YOUR CHECKLIST</span><h3>完成这三件事</h3>${c.checks.map((s,i)=>`<label class="check-line"><input class="task-check" type="checkbox" data-lesson-check="${c.id}" data-index="${i}" ${checks[i]?'checked':''}>${s}</label>`).join('')}<button class="btn ${done?'secondary':''}" style="width:100%;margin-top:14px" data-action="complete" data-id="${c.id}">${done?'✓ 已完成 · 点击撤销':'标记本模块完成'}</button><p class="source-note">按实际完成情况自评。完成标记不等于能力测评合格。</p></section><section class="panel"><span class="eyebrow">LEARNING RESOURCES</span><h3>配套学习入口</h3>${c.resources.map(resource).map(sourceLink).join('')}<p class="source-note">学习：先尝试再看答案。测试：独立完成后才核对。</p></section><section class="panel"><h3>本周输出</h3><p class="sub">3段录音 · 2封邮件<br>1份短业务文档 · 1次测试</p><a class="article-link" href="#progress">记录本周进度 ↗</a></section>${c.id<12?`<a class="panel article-link" href="#lesson/${c.id+1}">下一模块：${course(c.id+1).title} →</a>`:''}</aside></div>`;}
function promptFor(c,kind){return `请作为制造业外企英语教练，与我练习“${c.title}”。我的背景是统计学，目标为项目管理或数据分析岗。任务：${kind==='writing'?c.writing:c.speaking} 请先给必要的虚构背景，一次只问一个问题，等待我回答。先不要给参考答案；结束后引用原句，只改最影响理解的三个问题，让我自己重写或重说。不编造我的真实经历。只有文字时，不评价发音或实际口语流畅度。`;}
function practice(id){const c=course(id||nextCourse().id),kind=new URLSearchParams(location.hash.split('?')[1]||'').get('kind')||'writing',key=`${c.id}-${kind}`,draft=state.drafts[key]||'';$('#main').innerHTML=pageHead('THE PRACTICE DESK','先独立表达，再修改一次。','在这里留下首稿与想法。内容自动保存在当前浏览器；可以导出，或复制任务到对话工具中获得反馈。')+`<div class="practice-layout"><section class="panel"><div class="field-grid"><div><label class="field" for="practice-course">选择模块</label><select id="practice-course">${COURSES.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>W${x.week} · ${x.title}</option>`).join('')}</select></div><div><label class="field" for="practice-kind">练习方式</label><select id="practice-kind"><option value="writing" ${kind==='writing'?'selected':''}>邮件 / 书面表达</option><option value="speaking" ${kind==='speaking'?'selected':''}>口头表达 / 角色对话</option></select></div></div><div class="prompt-box">${kind==='writing'?c.writing:c.speaking}</div><label class="field" for="draft">${kind==='writing'?'英文首稿 / 修改稿':'英文关键词 / 录音后的自查记录'}</label><textarea id="draft" data-draft-key="${key}" placeholder="先自己写，暂时不看示例。可在首稿下面标注【修改稿】，保留变化。">${esc(draft)}</textarea><div class="draft-meta"><span id="word-count">${wc(draft)} English words</span><span id="save-status">浏览器本地自动保存</span></div><div class="btn-row"><button class="btn" data-action="export-draft" data-id="${c.id}" data-kind="${kind}">导出练习稿 ↓</button><button class="btn secondary" data-action="copy-prompt" data-id="${c.id}" data-kind="${kind}">复制陪练提示词</button><a class="btn light" href="#lesson/${c.id}">查看本课内容</a></div></section><aside class="lesson-aside"><section class="panel"><span class="eyebrow">RECORD & LISTEN</span><h3>听听自己怎么说</h3><p class="sub">录一段首版，回听数字、重点和长停顿，再尝试第二版。</p><div class="audio-controls"><button class="btn small" data-action="record" id="record-btn">● 开始录音</button><button class="btn secondary small" data-action="stop-record" id="stop-record-btn" disabled>停止</button></div><p id="record-status" class="source-note">需要浏览器麦克风权限。录音不上传，也不会自动长期保存，请下载留存。</p><audio id="recording" controls hidden></audio><a id="audio-download" class="article-link" download="english-practice.webm" hidden>下载本次录音 ↓</a></section><section class="panel"><span class="eyebrow">BEFORE YOU FINISH</span><h3>先检查业务，再检查语言</h3><ol class="step-list"><li>数字、日期、单位和责任人准确吗？</li><li>事实、推测、建议和批准区分了吗？</li><li>对方知道下一步要做什么吗？</li><li>能用更短、更自然的句子说清吗？</li></ol></section><section class="panel"><h3>需要写作反馈？</h3><p class="sub">本学习室保存草稿和任务；自动写作反馈可使用Cambridge工具。语音评分需实际音频证据。</p>${sourceLink(resource('writing'))}</section></aside></div>`;}
function tests(){if(activeQuiz)return renderQuiz();$('#main').innerHTML=pageHead('CHECK YOUR PROGRESS','让进步，有迹可循。','即时小测检查表达与业务理解；综合测评覆盖听读、邮件、口头汇报和互动。成绩只用于本计划的学习调整。')+`<div class="hero-grid"><section class="hero"><div class="hero-copy"><div class="hero-tag">QUICK CHECK · 25 QUESTIONS</div><h2>20分钟，检验一次<br>业务英语判断。</h2><p>随机抽取20道词汇题和5道业务题，提交后查看解释并复习错词。它不代替听力或口语测评。</p><button class="btn" data-action="start-quiz">开始即时小测 ↗</button></div></section><section class="panel"><span class="eyebrow">FULL ASSESSMENT</span><h2>60分钟综合测试</h2><p class="sub">听力20 · 阅读15 · 邮件25<br>口头汇报25 · 即时互动15</p><div class="progress-bar"><span style="width:100%"></span></div><p class="sub">起点、W4、W8、W12各测一次。按陌生任务完成，保留首次输出。</p><div class="btn-row"><a class="btn secondary small" href="#doc/1">查看完整试卷</a><a class="btn light small" href="#doc/2">评分与答案</a></div></section></div><div class="two-col"><section class="panel"><h2>综合成绩记录</h2><p class="sub">由你或评估者按评分标准录入。空白表示未测，0分表示实际得分为0；缺项时不计算完整总分。</p><form id="assessment-form"><div class="field-grid"><div><label class="field" for="assess-stage">测评阶段</label><select id="assess-stage"><option>起点测评</option><option>W4复测</option><option>W8复测</option><option>W12复测</option><option>补充测评</option></select></div><div><label class="field" for="assess-date">测评日期</label><input type="date" id="assess-date" value="${today()}" required></div></div><div class="score-inputs">${[['听力',20],['阅读',15],['邮件',25],['口头汇报',25],['语音互动',15]].map((x,i)=>`<div><label for="score-${i}">${x[0]}</label><small>满分 ${x[1]}</small><input id="score-${i}" type="number" min="0" max="${x[1]}" step="0.1" placeholder="未测"></div>`).join('')}</div><label class="field" for="assess-note" style="margin-top:18px">材料级别、条件与证据</label><textarea id="assess-note" class="record-note" placeholder="例如：B2听力，播放2遍；口语为实际录音评估。只有文字时，口头汇报与语音互动先留空。"></textarea><button class="btn" style="margin-top:15px">保存本次测评</button></form></section><section class="panel"><span class="eyebrow">A FAIR COMPARISON</span><h2>怎么测，才看得出进步？</h2><ol class="step-list"><li>初测听力使用B2的 A design presentation，最多2遍、不看原文。低于40%时，下次改B1并单独记录。</li><li>W4保留 A business interview；W8保留 Business news；W12保留 A lecture about an experiment，不提前作日常练习。</li><li>录音或真实语音互动才能评价发音和实际流畅度；文字稿不能补齐口语分。</li><li>比较用时、遗漏、数字准确性和行动闭环；不同试题难度并不完全相等。</li></ol><div class="note">练习分不换算为CEFR、雅思或企业录用线。</div></section></div><div class="section-head"><h2>最近的即时小测</h2><span>总分与错题均可导出</span></div><section class="panel">${state.quizResults.length?state.quizResults.slice().reverse().slice(0,5).map(r=>`<div class="log-entry"><div><strong>${esc(r.label)}</strong><span>${esc(r.date)} · ${r.correct}/${r.total} 答对</span></div><div class="minutes">${Math.round(r.correct/r.total*100)}<small style="font:10px sans-serif">%</small></div></div>`).join(''):'<div class="empty">还没有测验记录。先做25题测验，熟悉词汇与业务题型。</div>'}</section>`;mountVocabularyTestPanel();}
function startQuiz(id,options={}){const business=id?course(id).questions.map((q,i)=>({...q,id:`${id}-${i}`})):COURSES.flatMap(c=>c.questions.map((q,i)=>({...q,id:`${c.id}-${i}`})));let bank,label,minutes;if(options.vocabularyOnly){bank=shuffled(vocabularyQuestionBank(id)).slice(0,25);label=id?`W${id} 词汇专项 · 25题`:'跨章节词汇专项 · 25题';minutes=15;}else if(id){bank=shuffled([...business,...vocabularyQuestionBank(id)]);label=`W${id} 章节测验 · 25词汇＋2业务`;minutes=20;}else{bank=shuffled([...shuffled(vocabularyQuestionBank()).slice(0,20),...shuffled(business).slice(0,5)]);label='综合即时测验 · 20词汇＋5业务';minutes=20;}activeQuiz={questions:bank,answers:{},deadline:Date.now()+minutes*60000,label,submitted:false};location.hash='#tests';renderQuiz();clearInterval(quizTimer);quizTimer=setInterval(tickQuiz,1000);tickQuiz();}
function renderQuiz(){const qz=activeQuiz;if(!qz)return tests();const correct=qz.questions.filter((q,i)=>Number(qz.answers[i])===q.a).length;$('#main').innerHTML=pageHead('PRACTISE → CHECK → REVIEW',qz.submitted?'把错题，变成下一次会用的表达。':qz.label,qz.submitted?'请先看解释，再到课程中换一个情境复用。':'独立作答，提交后才显示正确答案。答题状态在本次页面内保留，刷新页面将结束本次未提交测试。')+`<section class="panel">${qz.submitted?`<div class="score-big">${Math.round(correct/qz.questions.length*100)}<small> % · ${correct}/${qz.questions.length} 答对</small></div>`:`<div class="test-actions"><span class="sub">实用词汇 · 业务信息准确性 · 表达选择</span><span class="timer" id="quiz-clock">--:--</span></div>`}<form id="quiz-form">${qz.questions.map((q,i)=>`<div class="quiz-question"><h3>${i+1}. ${esc(q.q)}</h3>${q.options.map((op,j)=>`<label class="quiz-option ${qz.submitted?(j===q.a?'correct':Number(qz.answers[i])===j?'wrong':''):''}"><input type="radio" name="q${i}" value="${j}" data-q="${i}" ${Number(qz.answers[i])===j?'checked':''} ${qz.submitted?'disabled':''}>${esc(op)}</label>`).join('')}${qz.submitted?`<div class="explanation">${Number(qz.answers[i])===q.a?'✓ 回答正确':'需复习'} · ${esc(q.why)}</div>`:''}</div>`).join('')}<div class="btn-row">${qz.submitted?'<button type="button" class="btn" data-action="finish-quiz">返回测试中心</button><button type="button" class="btn secondary" data-action="export-quiz">导出结果与错题 ↓</button>':'<button class="btn">提交并查看解释</button><button type="button" class="btn secondary" data-action="cancel-quiz">退出本次小测</button>'}</div></form></section>`;tickQuiz();mountVocabularyScore(qz);}
function tickQuiz(){if(!activeQuiz||activeQuiz.submitted)return;const sec=Math.max(0,Math.ceil((activeQuiz.deadline-Date.now())/1000)),clock=$('#quiz-clock');if(clock)clock.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;if(sec===0)submitQuiz(true);}
function submitQuiz(timed=false){if(!activeQuiz||activeQuiz.submitted)return;activeQuiz.submitted=true;clearInterval(quizTimer);const r={date:today(),label:activeQuiz.label,correct:activeQuiz.questions.filter((q,i)=>Number(activeQuiz.answers[i])===q.a).length,total:activeQuiz.questions.length,questions:activeQuiz.questions,answers:activeQuiz.answers};trackVocabularyResult(activeQuiz.questions,activeQuiz.answers);state.quizResults.push(r);save();renderQuiz();if(timed)toast('时间已到，已按现有答案提交。');}
function resources(){const filter=new URLSearchParams(location.hash.split('?')[1]||'').get('type')||'全部';$('#main').innerHTML=pageHead('YOUR CURATED SHELF','少一点收藏，多一点真正练习。','按任务选择资源：口语和邮件先用British Council；写作借助Cambridge反馈；后期加入制造业案例。')+`<div class="filter-bar">${['全部','口语','听力','写作','行业阅读','词汇','测评'].map(t=>`<button class="filter-btn ${t===filter?'active':''}" data-resource-filter="${t}">${t}</button>`).join('')}</div><div class="resource-grid">${RESOURCES.filter(r=>filter==='全部'||r.type===filter).map(r=>`<section class="resource-card"><span class="org">${r.org.toUpperCase()}</span><h3>${r.title}</h3><div class="badge-line"><span class="chip">${r.type}</span><span class="chip">${r.level}</span></div><p>${r.note}</p><a class="btn secondary small" href="${r.url}" target="_blank" rel="noopener noreferrer">前往学习 ↗</a></section>`).join('')}</div><p class="source-note">学习资源与开源说明核验于2026-10-25。外部网站独立运营，部分功能需注册或付费；音视频可用性取决于网络和设备。</p><div class="section-head" id="opensource"><h2>开源项目，怎么借鉴？</h2><a href="#doc/4">查看选型文档 ↗</a></div><p class="sub">本学习室独立实现，借鉴学习流程，提供专项工具入口；没有嵌入下列项目源码，也没有接入其AI服务。</p><div class="project-grid" style="margin-top:20px">${PROJECTS.map(p=>`<section class="panel"><h3>${p.name}<span class="chip">${p.license}</span></h3><p>${p.use}</p><p class="muted">${p.fit}</p><div class="note">${p.choice}</div><div class="btn-row"><a class="btn secondary small" href="${p.url}" target="_blank" rel="noopener noreferrer">查看官方仓库 ↗</a></div></section>`).join('')}</div><div class="section-head"><h2>完整学习文档</h2><span>可在线阅读，也可下载</span></div><section class="panel">${DOCS.map((d,i)=>`<a class="doc-row" href="#doc/${i}">${d[0]}<span>阅读 / 下载 ↗</span></a>`).join('')}</section>`;}
function progress(){const days=Array.from({length:28},(_,i)=>{const d=new Date();d.setUTCDate(d.getUTCDate()-(27-i));return dateKey(d);}),logged=new Set(state.logs.map(l=>l.date));$('#main').innerHTML=pageHead('YOUR LEARNING RECORD','把做过的练习，留成自己的积累。','记录实际用时、测试结果与反复出现的问题。记录存于此浏览器；更换设备前请导出备份。')+`<div class="two-col"><section class="panel"><span class="eyebrow">LAST 28 DAYS</span><h2>保持节奏，也允许停下来。</h2><div class="heatmap">${days.map(d=>`<div class="heat-day ${logged.has(d)?'logged':''} ${d===today()?'today':''}" title="${d} · ${state.logs.filter(l=>l.date===d).reduce((s,l)=>s+l.minutes,0)}分钟" aria-label="${d} ${logged.has(d)?'有学习记录':'无学习记录'}"></div>`).join('')}</div><div class="draft-meta"><span>浅色：无记录 · 绿色：有学习记录</span><span>轮廓：今天</span></div><div class="mini-stat-grid"><div class="mini-stat"><strong>${logged.size}</strong><span>记录天数</span></div><div class="mini-stat"><strong>${(totalMinutes()/60).toFixed(1)}</strong><span>学习小时</span></div><div class="mini-stat"><strong>${state.completed.length}</strong><span>完成模块</span></div></div></section><section class="panel"><h2>记录一次学习</h2><form id="log-form"><div class="field-grid"><div><label class="field" for="log-date">日期</label><input type="date" id="log-date" value="${today()}" required></div><div><label class="field" for="log-min">实际分钟</label><input type="number" id="log-min" value="90" min="1" max="720" required></div></div><label class="field" for="log-task" style="margin-top:14px">任务与本次最重要的改进</label><input id="log-task" type="text" style="width:100%" maxlength="300" placeholder="例如：W3周报；把soon换成责任人和具体时点" required><button class="btn" style="margin-top:15px">保存学习记录</button></form></section></div><div class="section-head"><h2>综合测评记录</h2><a href="#tests">录入新成绩 ↗</a></div><section class="panel score-table-wrap">${state.assessments.length?`<table class="score-table"><thead><tr><th>阶段 / 日期</th><th>听 /20</th><th>读 /15</th><th>写 /25</th><th>说 /25</th><th>互动 /15</th><th>总计</th><th></th></tr></thead><tbody>${state.assessments.slice().reverse().map((a,i)=>{const n=a.scores.filter(x=>x!==null).length,total=a.scores.reduce((s,x)=>s+(x||0),0);return `<tr><td>${esc(a.stage)}<br><span class="muted">${esc(a.date)}</span>${a.note?`<br><small>${esc(a.note)}</small>`:''}</td>${a.scores.map(s=>`<td>${s===null?'未测':s}</td>`).join('')}<td>${n===5?`${total.toFixed(1)}/100`:`已测${n}项`}</td><td><button class="text-btn" data-delete-assessment="${state.assessments.length-1-i}">删除</button></td></tr>`;}).join('')}</tbody></table>`:'<div class="empty">还没有综合测评。先完成起点测试，再按评分标准录入。</div>'}</section><div class="two-col" style="margin-top:22px"><section class="panel"><h2>最近的学习记录</h2>${state.logs.length?state.logs.slice().reverse().slice(0,12).map(l=>`<div class="log-entry"><div><strong>${esc(l.task)}</strong><span>${esc(l.date)}</span></div><div class="minutes">${l.minutes}<small style="font:10px sans-serif"> min</small></div><button class="text-btn" data-delete-log="${esc(l.id)}">删除</button></div>`).join(''):'<div class="empty">从今天的一次练习开始记录。</div>'}</section><section class="panel"><h2>下阶段，只主攻一个短板</h2><label class="field" for="personal-notes">我的反复错误与下周重点</label><textarea id="personal-notes" style="min-height:185px" placeholder="记录最影响理解的三个错误，以及下周只重点改善的一件事。">${esc(state.notes)}</textarea><div class="btn-row"><button class="btn secondary small" data-action="export-state">导出全部记录 ↓</button><button class="btn light small" data-action="import-state">导入备份</button></div><p class="source-note">导出包含草稿、学习日志与测评；录音需单独下载。不同域名或设备的数据不会自动同步。</p></section></div>`;}
function inlineMd(t){return esc(t).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a class="inline-link" href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdown(t){const lines=t.split('\n');let out='',table=false,list=false;const closeList=()=>{if(list){out+='</ul>';list=false;}};for(const line of lines){if(line.startsWith('|')){closeList();if(/^\|[\s:|-]+\|\s*$/.test(line))continue;const cells=line.trim().replace(/^\||\|$/g,'').split('|');if(!table){out+='<div class="score-table-wrap"><table class="score-table">';table=true;}out+='<tr>'+cells.map(c=>`<td>${inlineMd(c.trim())}</td>`).join('')+'</tr>';continue;}if(table){out+='</table></div>';table=false;}if(/^#{1,3} /.test(line)){closeList();const n=line.match(/^#+/)[0].length;out+=`<h${n} style="margin-top:25px">${inlineMd(line.slice(n+1))}</h${n}>`;}else if(/^[-*] |^\d+\. /.test(line)){if(!list){out+='<ul class="step-list">';list=true;}out+=`<li>${inlineMd(line.replace(/^[-*] |^\d+\. /,''))}</li>`;}else{closeList();if(line.trim())out+=`<p>${inlineMd(line.replace(/^>\s?/,''))}</p>`;}}closeList();if(table)out+='</table></div>';return out;}
function doc(id){const i=Number(id),d=DOCS[i];if(!d){location.hash='#resources';return;}const content=window.DOC_CONTENT?.[i];$('#main').innerHTML=pageHead('THE COMPLETE GUIDE',d[0],'完整材料整理成文档，方便查阅、打印或带到其他工具中练习。')+`<div class="btn-row" style="margin:0 0 22px"><button class="btn secondary" data-action="download-doc" data-id="${i}">下载Markdown ↓</button><button class="btn light" data-action="print">打印 / 保存PDF</button><a class="btn light" href="#resources">返回资源区</a></div><article class="panel" style="max-width:1000px">${content?markdown(content):'<p>文档加载失败，请从本地docs目录打开学习材料。</p>'}</article>`;}
function route(){if(window.cleanupVocabulary)window.cleanupVocabulary();if(window.cleanupListening)window.cleanupListening();if(recorder&&recorder.state==='recording')recorder.stop();if('speechSynthesis'in window)speechSynthesis.cancel();const [path]=location.hash.slice(1).split('?'),[page='home',id]=path.split('/'),labels={home:'今日学习',courses:'12周课程',lesson:'12周课程',practice:'练习工作台',tests:'测试中心',audio:'听力跟读',vocab:'词汇学习',resources:'资源与开源参考',progress:'学习档案',doc:'学习文档'};$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(page==='lesson'?'courses':page==='doc'?'resources':page)));$('#page-label').textContent=labels[page]||labels.home;({home,courses,lesson:()=>lesson(id),practice:()=>practice(id),tests,audio:()=>renderListening(id),vocab:()=>renderVocabulary(id),resources,progress,doc:()=>doc(id)}[page]||home)();if(page==='lesson'&&window.mountLessonAudio)window.mountLessonAudio(Number(id));if(page==='lesson'&&window.mountLessonVocabulary)window.mountLessonVocabulary(Number(id));updateSide();window.scrollTo(0,0);}
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-daily]')){state.daily[today()]||={};state.daily[today()][el.dataset.daily]=el.checked;save();}if(el.matches('[data-lesson-check]')){const id=el.dataset.lessonCheck;state.checks[id]||={};state.checks[id][el.dataset.index]=el.checked;save();}if(el.matches('[data-q]')&&activeQuiz)activeQuiz.answers[el.dataset.q]=Number(el.value);if(el.id==='practice-course'||el.id==='practice-kind')location.hash=`#practice/${$('#practice-course').value}?kind=${$('#practice-kind').value}`;});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='draft'){state.drafts[el.dataset.draftKey]=el.value;save();$('#word-count').textContent=`${wc(el.value)} English words`;$('#save-status').textContent=storageOK?'已保存到此浏览器':'存储受限，请导出';}if(el.id==='personal-notes'){state.notes=el.value;save();}if(el.id==='course-search'){const q=el.value.toLowerCase();$$('.course-card').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='quiz-form'){submitQuiz();return;}if(e.target.id==='log-form'){const minutes=Number($('#log-min').value),task=$('#log-task').value.trim(),date=$('#log-date').value;if(!task||!date||!Number.isFinite(minutes)||minutes<1||minutes>720)return toast('请填写有效的日期、任务和实际分钟。');state.logs.push({id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),date,minutes,task});save();progress();toast('学习记录已保存。');}if(e.target.id==='assessment-form'){const maxima=[20,15,25,25,15],scores=maxima.map((m,i)=>$('#score-'+i).value===''?null:Number($('#score-'+i).value));if(scores.every(s=>s===null))return toast('请至少填写一个已测项目，未测项目留空。');if(scores.some((s,i)=>s!==null&&(!Number.isFinite(s)||s<0||s>maxima[i])))return toast('请检查分数范围。');state.assessments.push({stage:$('#assess-stage').value,date:$('#assess-date').value,scores,note:$('#assess-note').value.trim()});save();toast('测评已保存，缺项将标记为未测。');location.hash='#progress';}});
document.addEventListener('click',async e=>{const track=e.target.closest('[data-track]');if(track){location.hash=`#courses?track=${encodeURIComponent(track.dataset.track)}`;return;}const rf=e.target.closest('[data-resource-filter]');if(rf){location.hash=`#resources?type=${encodeURIComponent(rf.dataset.resourceFilter)}`;return;}const dl=e.target.closest('[data-delete-log]');if(dl){state.logs=state.logs.filter(l=>l.id!==dl.dataset.deleteLog);save();progress();return;}const da=e.target.closest('[data-delete-assessment]');if(da){state.assessments.splice(Number(da.dataset.deleteAssessment),1);save();progress();return;}const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id),c=course(id);switch(b.dataset.action){
case'complete':if(state.completed.includes(id))state.completed=state.completed.filter(x=>x!==id);else{if(![0,1,2].every(i=>state.checks[id]?.[i]))return toast('请先按实际情况完成并勾选三项自检。');state.completed.push(id);}save();lesson(id);break;
case'log-today':location.hash='#progress';break;
case'copy-sample':copy(c.sample);break;
case'speak-sample':if(!('speechSynthesis'in window))return toast('此浏览器不支持合成朗读，请使用外部学习材料。');speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(c.sample);utter.lang='en-US';utter.rate=.9;utter.onerror=()=>toast('合成朗读不可用，请检查设备语音设置。');speechSynthesis.speak(utter);break;
case'copy-prompt':copy(promptFor(c,b.dataset.kind));break;
case'export-draft':download(`W${id}_${b.dataset.kind}_${today()}.md`,`# W${id} ${c.title}\n\n任务：${b.dataset.kind==='writing'?c.writing:c.speaking}\n\n${state.drafts[`${id}-${b.dataset.kind}`]||''}\n`);break;
case'start-quiz':startQuiz();break;case'lesson-quiz':startQuiz(id);break;
case'cancel-quiz':clearInterval(quizTimer);activeQuiz=null;tests();break;
case'finish-quiz':activeQuiz=null;tests();break;
case'export-quiz':if(activeQuiz)download(`小测_${today()}.md`,`# ${activeQuiz.label}\n\n${activeQuiz.questions.map((q,i)=>`${i+1}. ${q.q}\n你的选择：${q.options[activeQuiz.answers[i]]||'未答'}\n正确答案：${q.options[q.a]}\n解释：${q.why}`).join('\n\n')}`);break;
case'download-doc':if(window.DOC_CONTENT?.[id])download(DOCS[id][1],DOC_CONTENT[id]);break;case'print':window.print();break;
case'export-state':download(`职场英语学习记录_${today()}.json`,JSON.stringify(state,null,2),'application/json');break;
case'import-state':$('#import-file').click();break;
case'record':await startRecording();break;case'stop-record':if(recorder?.state==='recording')recorder.stop();break;
}});
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('此浏览器不支持录音，可使用系统录音工具后回听。');try{const stream=await navigator.mediaDevices.getUserMedia({audio:true}),chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(audioURL)URL.revokeObjectURL(audioURL);const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});audioURL=URL.createObjectURL(blob);const audio=$('#recording'),link=$('#audio-download');if(audio){audio.src=audioURL;audio.hidden=false;link.href=audioURL;link.download=`english-practice-${today()}.${blob.type.includes('mp4')?'m4a':blob.type.includes('ogg')?'ogg':'webm'}`;link.hidden=false;$('#record-btn').disabled=false;$('#stop-record-btn').disabled=true;$('#record-status').textContent='录音已准备好。请回听并下载，离开本页后需重新录制。';}};recorder.start();$('#record-btn').disabled=true;$('#stop-record-btn').disabled=false;$('#record-status').textContent='正在录音… 完成后点击停止。';}catch{toast('未能访问麦克风，请检查浏览器权限或使用系统录音工具。');}}
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('备份过大，请选择本学习室导出的JSON文件。');e.target.value='';return;}try{const obj=JSON.parse(await f.text()),validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s);if(obj.version!==1||!Array.isArray(obj.completed)||!obj.completed.every(i=>Number.isInteger(i)&&i>=1&&i<=12)||!Array.isArray(obj.logs)||!obj.logs.every(l=>validDate(l.date)&&Number.isFinite(l.minutes)&&l.minutes>=1&&l.minutes<=720&&typeof l.task==='string'&&typeof l.id==='string')||!Array.isArray(obj.assessments)||!obj.assessments.every(a=>Array.isArray(a.scores)&&a.scores.length===5&&a.scores.every((s,i)=>s===null||(Number.isFinite(s)&&s>=0&&s<=[20,15,25,25,15][i]))&&validDate(a.date)&&typeof a.stage==='string')||!Array.isArray(obj.quizResults)||!obj.quizResults.every(q=>Number.isFinite(q.correct)&&Number.isFinite(q.total)&&q.total>0&&q.correct>=0&&q.correct<=q.total&&typeof q.label==='string')||!obj.drafts||typeof obj.drafts!=='object'||!Object.values(obj.drafts).every(x=>typeof x==='string')||(obj.vocabProgress!==undefined&&(!obj.vocabProgress||typeof obj.vocabProgress!=='object'||Array.isArray(obj.vocabProgress)||!Object.values(obj.vocabProgress).every(v=>v&&['new','review','known'].includes(v.status))))||!obj.checks||typeof obj.checks!=='object'||!obj.daily||typeof obj.daily!=='object'||typeof obj.notes!=='string')throw Error('invalid');if(!confirm('导入将替换当前浏览器中的学习记录。建议先导出当前记录。继续导入吗？'))return;state={...blank(),...obj,completed:[...new Set(obj.completed)]};save();route();toast('备份已导入。');}catch{toast('备份格式不正确，当前记录未改变。');}finally{e.target.value='';}});
window.addEventListener('hashchange',route);window.addEventListener('beforeunload',()=>{if(recorder?.state==='recording')recorder.stop();});updateSide();route();
